<?php
class FuelLogistics extends Model
{
 protected $table='fuel_stocks';
 public function references(){ $p=[];$scope=Auth::siteClause('a.site_id',$p);return['fuelTypes'=>$this->query("SELECT * FROM fuel_types WHERE status='active' AND deleted_at IS NULL ORDER BY name")->fetchAll(),'suppliers'=>$this->query("SELECT fs.id,s.name FROM fuel_suppliers fs JOIN suppliers s ON s.id=fs.supplier_id WHERE fs.status='active' AND fs.deleted_at IS NULL ORDER BY s.name")->fetchAll(),'allSuppliers'=>$this->query("SELECT id,name FROM suppliers WHERE status='active' AND deleted_at IS NULL ORDER BY name")->fetchAll(),'assets'=>$this->query("SELECT a.*,s.code site_code FROM logistics_assets a JOIN sites s ON s.id=a.site_id WHERE a.status='active' AND a.deleted_at IS NULL{$scope} ORDER BY a.code",$p)->fetchAll(),'people'=>$this->scoped('logistics_people','site_id'),'centers'=>$this->scoped('cost_centers','site_id'),'routes'=>$this->query("SELECT * FROM logistics_routes WHERE status='active' AND deleted_at IS NULL ORDER BY code")->fetchAll(),'trucks'=>$this->query("SELECT id,plate_number FROM trucks WHERE status='active' AND deleted_at IS NULL ORDER BY plate_number")->fetchAll(),'machines'=>$this->query("SELECT id,site_id,code,name FROM machines WHERE status='active' AND deleted_at IS NULL ORDER BY code")->fetchAll()];}
 public function dashboard(){return['stocks'=>$this->stocks(),'orders'=>$this->orders(),'missions'=>$this->missions(),'distributions'=>$this->distributions(),'kpis'=>$this->kpis()];}
 public function registerSupplier($supplier){$this->query("INSERT INTO fuel_suppliers(supplier_id) VALUES(:id) ON DUPLICATE KEY UPDATE status='active',deleted_at=NULL",['id'=>$supplier]);}
 public function createAsset(array$d,array$u){$site=(int)$d['site_id'];Auth::requireSiteAccess($site);$type=$d['asset_type'];$meter=$type==='vehicle'?'odometer':'hour_meter';$truck=!empty($d['truck_id'])?(int)$d['truck_id']:null;$machine=!empty($d['machine_id'])?(int)$d['machine_id']:null;if($type==='vehicle'&&!$truck)throw new RuntimeException('Le camion associé est obligatoire pour un véhicule.');if($type==='machine'&&!$machine)throw new RuntimeException('La machine associée est obligatoire.');$this->query("INSERT INTO logistics_assets(site_id,truck_id,machine_id,code,name,asset_type,meter_type,current_meter) VALUES(:site,:truck,:machine,:code,:name,:type,:meter,:current)",['site'=>$site,'truck'=>$truck,'machine'=>$machine,'code'=>strtoupper(trim($d['code'])),'name'=>trim($d['name']),'type'=>$type,'meter'=>$meter,'current'=>(float)$d['current_meter']]);}
 public function createPerson(array$d){$site=(int)$d['site_id'];Auth::requireSiteAccess($site);$this->query("INSERT INTO logistics_people(site_id,code,name,person_type,license_number) VALUES(:site,:code,:name,:type,:license)",['site'=>$site,'code'=>strtoupper(trim($d['code'])),'name'=>trim($d['name']),'type'=>$d['person_type'],'license'=>trim($d['license_number']??'')?:null]);}
 public function createNorm(array$d,array$u){$a=$this->asset($d['asset_id']);$basis=$a['meter_type']==='odometer'?'km':'hour';$rate=(float)$d['rate'];if($rate<=0)throw new RuntimeException('Norme invalide.');$this->query("INSERT INTO fuel_consumption_norms(asset_id,fuel_type_id,basis,rate,tolerance_percent,effective_from,effective_to,created_by) VALUES(:asset,:fuel,:basis,:rate,:tolerance,:start,:end,:user)",['asset'=>$a['id'],'fuel'=>$d['fuel_type_id'],'basis'=>$basis,'rate'=>$rate,'tolerance'=>(float)$d['tolerance_percent'],'start'=>$d['effective_from'],'end'=>trim($d['effective_to']??'')?:null,'user'=>$u['id']]);}
 public function createRoute(array$d){$distance=(float)$d['planned_distance_km'];if($distance<=0)throw new RuntimeException('Distance planifiée invalide.');$this->query("INSERT INTO logistics_routes(code,name,origin_site_id,destination_site_id,planned_distance_km) VALUES(:code,:name,:origin,:destination,:distance)",['code'=>strtoupper(trim($d['code'])),'name'=>trim($d['name']),'origin'=>$d['origin_site_id']?:null,'destination'=>$d['destination_site_id']?:null,'distance'=>$distance]);}
 public function createOrder(array$d,array$u){$site=Auth::requireCurrentSite();$this->assertCenter($d['cost_center_id'],$site);if((float)$d['quantity']<=0||(float)$d['unit_cost']<0)throw new RuntimeException('Quantité ou coût invalide.');$this->db->beginTransaction();try{$n='BC-CARB-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO fuel_purchase_orders(site_id,cost_center_id,fuel_supplier_id,order_number,status,ordered_at,created_by) VALUES(:site,:center,:supplier,:number,'draft',:at,:user)",['site'=>$site,'center'=>$d['cost_center_id'],'supplier'=>$d['fuel_supplier_id'],'number'=>$n,'at'=>$d['ordered_at'],'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();$this->query("INSERT INTO fuel_purchase_order_lines(purchase_order_id,fuel_type_id,ordered_quantity,unit_cost) VALUES(:po,:fuel,:qty,:cost)",['po'=>$id,'fuel'=>$d['fuel_type_id'],'qty'=>$d['quantity'],'cost'=>$d['unit_cost']]);require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('BC',$site,'fuel_purchase_orders',$id,'draft',$d['ordered_at'],$u,(float)$d['quantity']*(float)$d['unit_cost']);$this->logActivity('create','fuel-logistics','fuel_purchase_orders',$id,'Création bon de commande carburant.',null,$d,$u);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function submitOrder($id,array$u){$this->transitionOrder($id,'draft','submitted',$u,false);}
 public function approveOrder($id,array$u){$this->transitionOrder($id,'submitted','approved',$u,true);}
 private function transitionOrder($id,$from,$to,array$u,$approval){$this->db->beginTransaction();try{$o=$this->row('SELECT * FROM fuel_purchase_orders WHERE id=? FOR UPDATE',[$id]);if(!$o||$o['status']!==$from)throw new RuntimeException('Transition de commande interdite.');Auth::requireSiteAccess($o['site_id']);if($approval&&(int)$o['created_by']===(int)$u['id'])throw new RuntimeException('Le créateur ne peut pas valider sa commande.');$sql="UPDATE fuel_purchase_orders SET status=:status".($approval?',approved_by=:user,approved_at=NOW()':'')." WHERE id=:id";$x=['status'=>$to,'id'=>$id];if($approval)$x['user']=$u['id'];$this->query($sql,$x);$this->logActivity($to,'fuel-logistics','fuel_purchase_orders',$id,'Changement de statut commande.',[$from],[$to],$u);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function receiveOrder($id,$quantity,$key,array$u){$this->db->beginTransaction();try{$old=$this->row('SELECT id FROM fuel_receipts WHERE idempotency_key=? FOR UPDATE',[$key]);if($old){$this->db->commit();return(int)$old['id'];}$o=$this->row('SELECT * FROM fuel_purchase_orders WHERE id=? FOR UPDATE',[$id]);if(!$o||!in_array($o['status'],['approved','partially_received'],true))throw new RuntimeException('Commande non réceptionnable.');Auth::requireSiteAccess($o['site_id']);$l=$this->row('SELECT * FROM fuel_purchase_order_lines WHERE purchase_order_id=? FOR UPDATE',[$id]);$q=(float)$quantity;$left=(float)$l['ordered_quantity']-(float)$l['received_quantity'];if($q<=0||$q>$left)throw new RuntimeException('Quantité réceptionnée supérieure au reliquat.');$n='BRA-CARB-'.date('YmdHis').'-'.random_int(100,999);$this->query('INSERT INTO fuel_receipts(purchase_order_id,receipt_number,idempotency_key,received_at,received_by) VALUES(:po,:number,:key,NOW(),:user)',['po'=>$id,'number'=>$n,'key'=>$key,'user'=>$u['id']]);$rid=(int)$this->db->lastInsertId();$this->query('INSERT INTO fuel_receipt_lines(receipt_id,purchase_order_line_id,quantity,unit_cost) VALUES(:receipt,:line,:qty,:cost)',['receipt'=>$rid,'line'=>$l['id'],'qty'=>$q,'cost'=>$l['unit_cost']]);$s=$this->lockStock($o['site_id'],$l['fuel_type_id']);$before=(float)$s['physical_quantity'];$after=$before+$q;$avg=$after>0?(($before*(float)$s['average_unit_cost'])+($q*(float)$l['unit_cost']))/$after:(float)$l['unit_cost'];$this->query('UPDATE fuel_stocks SET physical_quantity=:after,average_unit_cost=:cost WHERE id=:id',['after'=>$after,'cost'=>$avg,'id'=>$s['id']]);$this->movement($s,'receipt',$q,$before,$after,$l['unit_cost'],'fuel_receipts',$rid,'receipt:'.$rid,$u);$newReceived=(float)$l['received_quantity']+$q;$status=$newReceived>=(float)$l['ordered_quantity']?'received':'partially_received';$this->query('UPDATE fuel_purchase_order_lines SET received_quantity=:q WHERE id=:id',['q'=>$newReceived,'id'=>$l['id']]);$this->query('UPDATE fuel_purchase_orders SET status=:status WHERE id=:id',['status'=>$status,'id'=>$id]);require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('BRA',$o['site_id'],'fuel_receipts',$rid,'approved',date('Y-m-d H:i:s'),$u,$q*(float)$l['unit_cost']);$this->db->commit();return$rid;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function distribute(array$d,array$u){$site=Auth::requireCurrentSite();$key=trim($d['idempotency_key']);$this->db->beginTransaction();try{$old=$this->row('SELECT id FROM fuel_distributions WHERE idempotency_key=? FOR UPDATE',[$key]);if($old){$this->db->commit();return(int)$old['id'];}$a=$this->row('SELECT * FROM logistics_assets WHERE id=? AND site_id=? AND status=\'active\' FOR UPDATE',[$d['asset_id'],$site]);$p=$this->row('SELECT * FROM logistics_people WHERE id=? AND site_id=? AND status=\'active\'',[$d['person_id'],$site]);if(!$a||!$p)throw new RuntimeException('Véhicule/équipement et chauffeur/opérateur obligatoires sur le site.');$this->assertCenter($d['cost_center_id'],$site);$before=(float)$d['meter_before'];$after=(float)$d['meter_after'];if($after<$before||$before<(float)$a['current_meter'])throw new RuntimeException('Valeurs de compteur chronologiquement incohérentes.');$qty=(float)$d['quantity'];$stock=$this->lockStock($site,$d['fuel_type_id']);if($qty<=0||$qty>((float)$stock['physical_quantity']-(float)$stock['reserved_quantity']))throw new RuntimeException('Stock de carburant disponible insuffisant.');$norm=$this->row("SELECT * FROM fuel_consumption_norms WHERE asset_id=? AND fuel_type_id=? AND status='active' AND deleted_at IS NULL AND effective_from<=DATE(?) AND (effective_to IS NULL OR effective_to>=DATE(?)) ORDER BY effective_from DESC,id DESC LIMIT 1 FOR UPDATE",[$a['id'],$d['fuel_type_id'],$d['distributed_at'],$d['distributed_at']]);$delta=$after-$before;$expected=null;$variance=null;$abnormal=0;if($norm){$expected=$norm['basis']==='km'?(float)$norm['rate']*$delta/100:(float)$norm['rate']*$delta;$variance=$expected>0?($qty-$expected)/$expected*100:($qty>0?100:0);$abnormal=$variance>(float)$norm['tolerance_percent']?1:0;}$n='DIST-CARB-'.date('YmdHis').'-'.random_int(100,999);$this->query('INSERT INTO fuel_distributions(site_id,cost_center_id,fuel_type_id,asset_id,person_id,mission_id,distribution_number,idempotency_key,quantity,unit_cost,meter_before,meter_after,normative_quantity,variance_percent,is_abnormal,distributed_at,created_by) VALUES(:site,:center,:fuel,:asset,:person,:mission,:number,:key,:qty,:cost,:before,:after,:norm,:variance,:abnormal,:at,:user)',['site'=>$site,'center'=>$d['cost_center_id'],'fuel'=>$d['fuel_type_id'],'asset'=>$a['id'],'person'=>$p['id'],'mission'=>!empty($d['mission_id'])?$d['mission_id']:null,'number'=>$n,'key'=>$key,'qty'=>$qty,'cost'=>$stock['average_unit_cost'],'before'=>$before,'after'=>$after,'norm'=>$expected,'variance'=>$variance,'abnormal'=>$abnormal,'at'=>$d['distributed_at'],'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();$remaining=(float)$stock['physical_quantity']-$qty;$this->query('UPDATE fuel_stocks SET physical_quantity=:q WHERE id=:id',['q'=>$remaining,'id'=>$stock['id']]);$this->query('UPDATE logistics_assets SET current_meter=:meter WHERE id=:id',['meter'=>$after,'id'=>$a['id']]);$this->movement($stock,'distribution',$qty,(float)$stock['physical_quantity'],$remaining,$stock['average_unit_cost'],'fuel_distributions',$id,'distribution:'.$id,$u);$this->logActivity('distribute','fuel-logistics','fuel_distributions',$id,$abnormal?'Distribution anormale détectée.':'Distribution carburant.',null,$d,$u);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createMission(array$d,array$u){$site=Auth::requireCurrentSite();$this->assertCenter($d['cost_center_id'],$site);$a=$this->asset($d['asset_id']);$p=$this->row('SELECT * FROM logistics_people WHERE id=? AND site_id=?',[$d['person_id'],$site]);if(!$p||$d['planned_end']<$d['planned_start'])throw new RuntimeException('Mission, conducteur ou chronologie invalide.');$n='OM-'.date('YmdHis').'-'.random_int(100,999);$this->db->beginTransaction();try{$this->query("INSERT INTO logistics_missions(ordering_site_id,cost_center_id,route_id,asset_id,person_id,mission_number,purpose,status,planned_start,planned_end,created_by) VALUES(:site,:center,:route,:asset,:person,:number,:purpose,'submitted',:start,:end,:user)",['site'=>$site,'center'=>$d['cost_center_id'],'route'=>$d['route_id']?:null,'asset'=>$a['id'],'person'=>$p['id'],'number'=>$n,'purpose'=>trim($d['purpose']),'start'=>$d['planned_start'],'end'=>$d['planned_end'],'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('OM',$site,'logistics_missions',$id,'submitted',$d['planned_start'],$u);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approveMission($id,array$u){$this->db->beginTransaction();try{$m=$this->mission($id,true);if($m['status']!=='submitted')throw new RuntimeException('Mission non validable.');if((int)$m['created_by']===(int)$u['id'])throw new RuntimeException('Le créateur ne peut pas valider sa mission.');$this->query("UPDATE logistics_missions SET status='approved',approved_by=:user WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function startMission($id,array$d){$this->missionStatus($id,'approved','in_progress','actual_start',$d['at'],'meter_start',$d['meter']);}
 public function completeMission($id,array$d){$this->missionStatus($id,'in_progress','justification_pending','actual_end',$d['at'],'meter_end',$d['meter']);}
 private function missionStatus($id,$from,$to,$dateField,$date,$meterField,$meter){$this->db->beginTransaction();try{$m=$this->mission($id,true);if($m['status']!==$from)throw new RuntimeException('Transition de mission interdite.');$a=$this->row('SELECT * FROM logistics_assets WHERE id=? FOR UPDATE',[$m['asset_id']]);if($to==='in_progress'&&($date<$m['planned_start']||$date>$m['planned_end']))throw new RuntimeException('Début de mission hors chronologie planifiée.');if($to==='justification_pending'&&($date<$m['actual_start']||(float)$meter<(float)$m['meter_start']))throw new RuntimeException('Fin de mission chronologiquement incohérente.');if((float)$meter<(float)$a['current_meter'])throw new RuntimeException('Compteur inférieur au dernier relevé.');$this->query("UPDATE logistics_missions SET status=:status,{$dateField}=:at,{$meterField}=:meter WHERE id=:id",['status'=>$to,'at'=>$date,'meter'=>$meter,'id'=>$id]);$this->query('UPDATE logistics_assets SET current_meter=:meter WHERE id=:id',['meter'=>$meter,'id'=>$a['id']]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function issueAdvance($mission,$amount,array$u){$this->db->beginTransaction();try{$m=$this->mission($mission,true);if(!in_array($m['status'],['approved','in_progress','justification_pending'],true)||(float)$amount<=0)throw new RuntimeException('Avance invalide.');$this->query("INSERT INTO mission_advances(mission_id,amount,status,issued_at,issued_by) VALUES(:mission,:amount,'issued',NOW(),:user)",['mission'=>$mission,'amount'=>$amount,'user'=>$u['id']]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function justify(array$d,array$u){$this->db->beginTransaction();try{$a=$this->row('SELECT a.*,m.ordering_site_id FROM mission_advances a JOIN logistics_missions m ON m.id=a.mission_id WHERE a.id=? FOR UPDATE',[$d['advance_id']]);if(!$a)throw new RuntimeException('Avance introuvable.');Auth::requireSiteAccess($a['ordering_site_id']);$amount=(float)$d['amount'];$complements=(float)$this->query("SELECT COALESCE(SUM(amount),0) FROM mission_adjustments WHERE advance_id=:id AND adjustment_type='complement'",['id'=>$a['id']])->fetchColumn();$used=(float)$this->query("SELECT COALESCE(SUM(amount),0) FROM mission_justifications WHERE advance_id=:id AND deleted_at IS NULL",['id'=>$a['id']])->fetchColumn();if($amount<=0||$used+$amount>(float)$a['amount']+$complements)throw new RuntimeException('Justification supérieure aux fonds disponibles.');$this->query('INSERT INTO mission_justifications(advance_id,expense_type,proof_reference,amount,expense_at,created_by) VALUES(:advance,:type,:proof,:amount,:at,:user)',['advance'=>$a['id'],'type'=>$d['expense_type'],'proof'=>trim($d['proof_reference']),'amount'=>$amount,'at'=>$d['expense_at'],'user'=>$u['id']]);$new=$used+$amount;$status=$new>=(float)$a['amount']+$complements?'justified':'partially_justified';$this->query('UPDATE mission_advances SET status=:status WHERE id=:id',['status'=>$status,'id'=>$a['id']]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function adjust(array$d,array$u){$a=$this->row('SELECT a.*,m.ordering_site_id FROM mission_advances a JOIN logistics_missions m ON m.id=a.mission_id WHERE a.id=?',[$d['advance_id']]);if(!$a||(float)$d['amount']<=0)throw new RuntimeException('Régularisation invalide.');Auth::requireSiteAccess($a['ordering_site_id']);$this->query('INSERT INTO mission_adjustments(advance_id,adjustment_type,amount,reference,adjusted_at,created_by) VALUES(:advance,:type,:amount,:reference,:at,:user)',['advance'=>$a['id'],'type'=>$d['adjustment_type'],'amount'=>$d['amount'],'reference'=>trim($d['reference']),'at'=>$d['adjusted_at'],'user'=>$u['id']]);}
 public function addToll(array$d,array$u){$m=$this->mission($d['mission_id']);if(!$m['route_id'])throw new RuntimeException('La mission doit avoir un trajet.');$this->query('INSERT INTO logistics_tolls(mission_id,route_id,location,amount,paid_at,proof_reference,created_by) VALUES(:mission,:route,:location,:amount,:at,:proof,:user)',['mission'=>$m['id'],'route'=>$m['route_id'],'location'=>trim($d['location']),'amount'=>$d['amount'],'at'=>$d['paid_at'],'proof'=>trim($d['proof_reference']??'')?:null,'user'=>$u['id']]);}
 public function settleMission($id){$this->db->beginTransaction();try{$m=$this->mission($id,true);if($m['status']!=='justification_pending')throw new RuntimeException('Mission non soldable.');$balance=(float)$this->query("SELECT COALESCE(SUM(a.amount),0)+COALESCE((SELECT SUM(x.amount) FROM mission_adjustments x JOIN mission_advances aa ON aa.id=x.advance_id WHERE aa.mission_id=:m2 AND x.adjustment_type='complement'),0)-COALESCE((SELECT SUM(j.amount) FROM mission_justifications j JOIN mission_advances aa ON aa.id=j.advance_id WHERE aa.mission_id=:m3 AND j.deleted_at IS NULL),0)-COALESCE((SELECT SUM(x.amount) FROM mission_adjustments x JOIN mission_advances aa ON aa.id=x.advance_id WHERE aa.mission_id=:m4 AND x.adjustment_type='refund'),0) FROM mission_advances a WHERE a.mission_id=:m",['m'=>$id,'m2'=>$id,'m3'=>$id,'m4'=>$id])->fetchColumn();if(abs($balance)>0.005)throw new RuntimeException('Mission non soldée: reliquat ou complément restant de '.number_format($balance,2,',',' '));$this->query("UPDATE logistics_missions SET status='settled' WHERE id=:id",['id'=>$id]);$this->query("UPDATE mission_advances SET status='settled' WHERE mission_id=:id",['id'=>$id]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function stocks(){$p=[];$s=Auth::siteClause('st.site_id',$p);return$this->query("SELECT st.*,si.code site_code,f.code fuel_code FROM fuel_stocks st JOIN sites si ON si.id=st.site_id JOIN fuel_types f ON f.id=st.fuel_type_id WHERE 1=1{$s} ORDER BY si.code,f.code",$p)->fetchAll();}
 public function orders(){$p=[];$s=Auth::siteClause('o.site_id',$p);return$this->query("SELECT o.*,si.code site_code,s.name supplier_name,l.ordered_quantity,l.received_quantity,l.unit_cost,f.code fuel_code FROM fuel_purchase_orders o JOIN sites si ON si.id=o.site_id JOIN fuel_suppliers fs ON fs.id=o.fuel_supplier_id JOIN suppliers s ON s.id=fs.supplier_id JOIN fuel_purchase_order_lines l ON l.purchase_order_id=o.id JOIN fuel_types f ON f.id=l.fuel_type_id WHERE o.deleted_at IS NULL{$s} ORDER BY o.id DESC",$p)->fetchAll();}
 public function missions(){$p=[];$s=Auth::siteClause('m.ordering_site_id',$p);return$this->query("SELECT m.*,si.code site_code,a.code asset_code,p.name person_name,r.code route_code,COALESCE((SELECT SUM(x.amount) FROM mission_advances x WHERE x.mission_id=m.id),0) advances,COALESCE((SELECT SUM(j.amount) FROM mission_justifications j JOIN mission_advances x ON x.id=j.advance_id WHERE x.mission_id=m.id AND j.deleted_at IS NULL),0) justified FROM logistics_missions m JOIN sites si ON si.id=m.ordering_site_id JOIN logistics_assets a ON a.id=m.asset_id JOIN logistics_people p ON p.id=m.person_id LEFT JOIN logistics_routes r ON r.id=m.route_id WHERE m.deleted_at IS NULL{$s} ORDER BY m.id DESC",$p)->fetchAll();}
 public function distributions(){$p=[];$s=Auth::siteClause('d.site_id',$p);return$this->query("SELECT d.*,si.code site_code,f.code fuel_code,a.code asset_code,p.name person_name FROM fuel_distributions d JOIN sites si ON si.id=d.site_id JOIN fuel_types f ON f.id=d.fuel_type_id JOIN logistics_assets a ON a.id=d.asset_id JOIN logistics_people p ON p.id=d.person_id WHERE 1=1{$s} ORDER BY d.id DESC LIMIT 100",$p)->fetchAll();}
 public function kpis(){$p=[];$s=Auth::siteClause('d.site_id',$p);$cons=$this->query("SELECT a.code asset_code,a.meter_type,SUM(d.quantity) actual,SUM(COALESCE(d.normative_quantity,0)) normative,SUM(d.quantity*d.unit_cost) cost,SUM(d.meter_after-d.meter_before) activity,COUNT(*) distributions,SUM(d.is_abnormal) anomalies FROM fuel_distributions d JOIN logistics_assets a ON a.id=d.asset_id WHERE 1=1{$s} GROUP BY a.id ORDER BY actual DESC",$p)->fetchAll();$tolls=$this->query("SELECT r.code route_code,SUM(t.amount) total,COUNT(*) passages FROM logistics_tolls t JOIN logistics_missions m ON m.id=t.mission_id JOIN logistics_routes r ON r.id=t.route_id WHERE 1=1".str_replace('d.site_id','m.ordering_site_id',$s)." GROUP BY r.id ORDER BY total DESC",$p)->fetchAll();$open=$this->query("SELECT COUNT(*) FROM logistics_missions m WHERE m.status IN('approved','in_progress','completed','justification_pending')".str_replace('d.site_id','m.ordering_site_id',$s),$p)->fetchColumn();return['consumption'=>$cons,'tolls'=>$tolls,'unsettled'=>(int)$open];}
 private function lockStock($site,$fuel){$this->query('INSERT IGNORE INTO fuel_stocks(site_id,fuel_type_id) VALUES(:site,:fuel)',['site'=>$site,'fuel'=>$fuel]);return$this->row('SELECT * FROM fuel_stocks WHERE site_id=? AND fuel_type_id=? FOR UPDATE',[$site,$fuel]);}
 private function movement($s,$type,$q,$before,$after,$cost,$source,$id,$key,array$u){if($before<0||$after<0)throw new RuntimeException('Un stock carburant ne peut devenir négatif.');$this->query('INSERT INTO fuel_stock_movements(stock_id,movement_type,quantity,quantity_before,quantity_after,unit_cost,source_type,source_id,effect_key,moved_at,created_by) VALUES(:stock,:type,:qty,:before,:after,:cost,:source,:source_id,:effect,NOW(),:user)',['stock'=>$s['id'],'type'=>$type,'qty'=>$q,'before'=>$before,'after'=>$after,'cost'=>$cost,'source'=>$source,'source_id'=>$id,'effect'=>$key,'user'=>$u['id']]);}
 private function asset($id){$a=$this->row('SELECT * FROM logistics_assets WHERE id=? AND deleted_at IS NULL',[$id]);if(!$a)throw new RuntimeException('Actif logistique introuvable.');Auth::requireSiteAccess($a['site_id']);$current=Auth::currentSiteId();if($current!==null&&(int)$a['site_id']!==(int)$current)throw new RuntimeException('Actif logistique hors du site courant.');return$a;}private function mission($id,$lock=false){$m=$this->row('SELECT * FROM logistics_missions WHERE id=? AND deleted_at IS NULL'.($lock?' FOR UPDATE':''),[$id]);if(!$m)throw new RuntimeException('Mission introuvable.');Auth::requireSiteAccess($m['ordering_site_id']);return$m;}private function assertCenter($id,$site){if(!$this->query('SELECT COUNT(*) FROM cost_centers WHERE id=:id AND site_id=:site AND status=\'active\' AND deleted_at IS NULL',['id'=>$id,'site'=>$site])->fetchColumn())throw new RuntimeException('Centre de coût hors du site commanditaire.');}private function scoped($table,$col){$p=[];$s=Auth::siteClause($col,$p);return$this->query("SELECT * FROM {$table} WHERE status='active' AND deleted_at IS NULL{$s} ORDER BY code",$p)->fetchAll();}private function row($sql,$p=[]){$q=$this->db->prepare($sql);$q->execute($p);return$q->fetch();}
}
